// Archivo (SIL Open Font License), latin subset, embedded so boards look the same everywhere.
export const ARCHIVO_FACES: { weight: number; b64: string }[] = [{"weight": 400, "b64": ""}, {"weight": 500, "b64": ""}, {"weight": 600, "b64": ""}, {"weight": 700, "b64": ""}];
export const FONT_CSS = ARCHIVO_FACES.map((f) => `@font-face{font-family:'Archivo';font-style:normal;font-weight:${f.weight};src:url(data:font/woff2;base64,${f.b64}) format('woff2')}`).join('');
